begin;
do $checks$
declare ad uuid; manager uuid; driver uuid; person uuid; company uuid; station uuid; foreign_station uuid; fuel uuid; op uuid:=gen_random_uuid(); blocked boolean; before_name text; n int:=0;
begin
 perform pg_advisory_xact_lock(17062026);
 select p.id into ad from public.perfiles p join auth.users au on au.id=p.id where au.email='fernando65120065@gmail.com';
 select p.id into manager from public.perfiles p join auth.users au on au.id=p.id where au.email='javier.quispe@filacero.test';
 select p.id into driver from public.perfiles p join auth.users au on au.id=p.id where au.email='ana.mendoza@filacero.test';
 select p.id into person from public.perfiles p join auth.users au on au.id=p.id where au.email='inactivo@filacero.test';
 select id,empresa_id into station,company from public.estaciones where nombre='San Jorge';
 select id into foreign_station from public.estaciones where nombre='Senkata';
 select combustible_id into fuel from public.estacion_combustible where estacion_id=station and activo limit 1;
 if ad is null or manager is null or driver is null or person is null or station is null then raise exception 'Carga antes las cuentas y el catálogo de exposición'; end if;
 perform set_config('request.jwt.claim.sub','',true);
 if jsonb_array_length(public.fc_query('catalog','{}')->'rows')<10 then raise exception 'Catálogo público incompleto'; end if;n:=n+1;
 blocked:=false;begin perform public.fc_query('users','{}');exception when others then blocked:=true;end;if not blocked then raise exception 'Visitante accede a usuarios';end if;n:=n+1;
 perform set_config('request.jwt.claim.sub',ad::text,true);
 blocked:=false;begin perform public.fc_command('user_state',jsonb_build_object('id',ad,'activo',false));exception when others then blocked:=true;end;if not blocked then raise exception 'Autodesactivación permitida';end if;n:=n+1;
 blocked:=false;begin perform public.fc_command('staff_save',jsonb_build_object('id',ad,'rol','conductor','nombre','Cambio propio'));exception when others then blocked:=true;end;if not blocked then raise exception 'Autocambio permitido';end if;n:=n+1;
 update public.perfiles set activo=true where id=person;
 perform public.fc_command('staff_save',jsonb_build_object('id',person,'nombre','Óscar Arce Mendoza','rol','responsable','empresa_id',company,'station_ids',jsonb_build_array(station)));
 if not exists(select 1 from public.vinculaciones_personal v join public.asignaciones_responsables a on a.vinculacion_id=v.id where v.perfil_id=person and v.activo and v.autorizada_en is not null and a.activo and a.estacion_id=station) then raise exception 'Alta directa no autoriza estación';end if;n:=n+1;
 if not exists(select 1 from jsonb_array_elements(public.fc_query('users','{"status":"active"}')) x where x->>'id'=person::text) then raise exception 'Alta no aparece en activos';end if;n:=n+1;
 select nombre into before_name from public.perfiles where id=person;
 blocked:=false;begin perform public.fc_command('staff_save',jsonb_build_object('id',person,'nombre','No debe guardarse','rol','responsable','empresa_id',company,'station_ids',jsonb_build_array(foreign_station)));exception when others then blocked:=true;end;
 if not blocked or (select nombre from public.perfiles where id=person)<>before_name then raise exception 'Asignación cruzada produjo cambios';end if;n:=n+1;
 blocked:=false;begin perform public.fc_command('staff_save',jsonb_build_object('id',person,'nombre',before_name,'rol','responsable','empresa_id',company,'station_ids',jsonb_build_array(station,station)));exception when others then blocked:=true;end;if not blocked then raise exception 'Acepta estaciones repetidas';end if;n:=n+1;
 perform set_config('request.jwt.claim.sub',person::text,true);
 if not private.fc_assigned(station) then raise exception 'Responsable sin permiso concedido';end if;n:=n+1;
 if private.fc_assigned(foreign_station) then raise exception 'Permiso cruzado';end if;n:=n+1;
 perform public.fc_command('publish',jsonb_build_object('id',station,'operation',op,'changes',jsonb_build_array(jsonb_build_object('id',fuel,'estado','disponible'))));
 perform public.fc_command('publish',jsonb_build_object('id',station,'operation',op,'changes',jsonb_build_array(jsonb_build_object('id',fuel,'estado','disponible'))));
 if (select count(*) from public.historial_disponibilidad where operacion_id=op)<>1 then raise exception 'Reintento duplica publicación';end if;n:=n+1;
 blocked:=false;begin perform public.fc_command('publish',jsonb_build_object('id',station,'operation',op,'changes',jsonb_build_array(jsonb_build_object('id',fuel,'estado','agotado'))));exception when others then blocked:=true;end;if not blocked then raise exception 'Reintento permite contenido distinto';end if;n:=n+1;
 perform set_config('request.jwt.claim.sub',ad::text,true);
 perform public.fc_command('user_state',jsonb_build_object('id',person,'activo',false));
 perform set_config('request.jwt.claim.sub',person::text,true);
 if private.fc_role() is not null then raise exception 'Sesión antigua mantiene cuenta inactiva';end if;n:=n+1;
 blocked:=false;begin perform public.fc_command('publish',jsonb_build_object('id',station,'operation',gen_random_uuid(),'changes',jsonb_build_array(jsonb_build_object('id',fuel,'estado','disponible'))));exception when others then blocked:=true;end;if not blocked then raise exception 'Cuenta inactiva publica';end if;n:=n+1;
 perform set_config('request.jwt.claim.sub',ad::text,true);
 perform public.fc_command('user_state',jsonb_build_object('id',person,'activo',true));
 perform public.fc_command('staff_save',jsonb_build_object('id',person,'nombre',before_name,'rol','responsable','empresa_id',company,'station_ids','[]'::jsonb));
 perform set_config('request.jwt.claim.sub',person::text,true);
 if private.fc_assigned(station) then raise exception 'Retirar asignación conserva permiso';end if;n:=n+1;
 if jsonb_array_length(public.fc_query('catalog','{"mode":"assigned"}')->'rows')<>0 then raise exception 'Sin asignar muestra estaciones';end if;n:=n+1;
 perform set_config('request.jwt.claim.sub',driver::text,true);
 blocked:=false;begin perform public.fc_command('staff_save',jsonb_build_object('id',driver,'nombre','Ana Mendoza Quispe','rol','administrador'));exception when others then blocked:=true;end;if not blocked then raise exception 'Conductor se eleva';end if;n:=n+1;
 perform public.fc_command('favorite',jsonb_build_object('id',station,'activo',true));
 perform public.fc_command('favorite',jsonb_build_object('id',station,'activo',true));
 if (select count(*) from public.favoritas where perfil_id=driver and estacion_id=station)<>1 then raise exception 'Favorita duplicada';end if;n:=n+1;
 perform public.fc_command('favorite',jsonb_build_object('id',station,'activo',false));
 if not exists(select 1 from public.favoritas where perfil_id=driver and estacion_id=station and not activo) then raise exception 'Favorita no aplica baja lógica';end if;n:=n+1;
 if has_table_privilege('authenticated','public.favoritas','select') or has_table_privilege('anon','public.perfiles','select') then raise exception 'Tablas expuestas directamente';end if;n:=n+1;
 if exists(select 1 from pg_class t join pg_namespace ns on ns.oid=t.relnamespace where ns.nspname='public' and t.relkind='r' and not t.relrowsecurity) then raise exception 'Tabla pública sin RLS';end if;n:=n+1;
 if exists(select 1 from pg_proc p join pg_namespace ns on ns.oid=p.pronamespace where ns.nspname='public' and p.proname in ('fc_query','fc_command') and p.prosecdef) then raise exception 'Entrada pública con privilegios de definidor';end if;n:=n+1;
 if n<>22 then raise exception 'Recuento inesperado %',n;end if;
end $checks$;
select '22 comprobaciones SQL aprobadas; los cambios de prueba se revierten' as resultado;
rollback;
